/**
 * dsh-provider-usage — upgrade 域配置形态割接（旧单模板/旧三周期默认 → 新三周期默认）。
 *
 * 只做形态割接，不做归一化：归一化单答案仍归 server/config/normalize.ts 的 normalizeReportConfig
 *（运行时读面），本步只把「用户从未自定义的旧默认文本」升级为三份新默认，把「自定义旧单模板」
 *展开为三周期同文本（用户文本不丢）。其它字段原样保留，promptTemplate 回填为 prompts.monthly
 *镜像（旧消费方兼容）。
 *
 * LEGACY 锁表经 server/shared/interface.ts 以纯数据复用（#768 A波2 由 config 下沉 shared；
 * S2 允许的 type-only/纯面复用——常量无副作用，非业务实例；normalizeReportConfig 本体不调用，
 * 避免把业务读面的归一化语义搬进迁移域）。
 * 读经注入（deps.readOldFile），写经同域原语（storage-layout.ts 的 writeFileAtomic 0600），
 * 坏文件容错（保持原状 + 诊断，不抛；启动期读盘数据不可信，抛即崩）。
 */
import { basename } from "node:path";
import type { ReportPrompts } from "../config/interface.ts";
import {
  DEFAULT_PROMPTS,
  LEGACY_DAILY_PROMPT_V1,
  LEGACY_DAILY_PROMPT_V2,
  LEGACY_DAILY_PROMPT_V3,
  LEGACY_DAILY_PROMPT_V4,
  LEGACY_MONTHLY_PROMPT_V1,
  LEGACY_MONTHLY_PROMPT_V2,
  LEGACY_MONTHLY_PROMPT_V3,
  LEGACY_MONTHLY_PROMPT_V4,
  LEGACY_PROMPT_TEMPLATE,
  LEGACY_WEEKLY_PROMPT_V1,
  LEGACY_WEEKLY_PROMPT_V2,
  LEGACY_WEEKLY_PROMPT_V3,
  LEGACY_WEEKLY_PROMPT_V4,
} from "../shared/interface.ts";
import type { UpgradeDeps } from "./deps.ts";
import { targetConfigFile, writeFileAtomic } from "./storage-layout.ts";

const LEGACY_DAILY: readonly string[] = [
  LEGACY_DAILY_PROMPT_V1,
  LEGACY_DAILY_PROMPT_V2,
  LEGACY_DAILY_PROMPT_V3,
  LEGACY_DAILY_PROMPT_V4,
];

const LEGACY_WEEKLY: readonly string[] = [
  LEGACY_WEEKLY_PROMPT_V1,
  LEGACY_WEEKLY_PROMPT_V2,
  LEGACY_WEEKLY_PROMPT_V3,
  LEGACY_WEEKLY_PROMPT_V4,
];

const LEGACY_MONTHLY: readonly string[] = [
  LEGACY_MONTHLY_PROMPT_V1,
  LEGACY_MONTHLY_PROMPT_V2,
  LEGACY_MONTHLY_PROMPT_V3,
  LEGACY_MONTHLY_PROMPT_V4,
];

/** 旧单模板默认（用户从未自定义）：统一升级为三份新默认 = 单答案。 */
function isLegacySingleDefault(text: string): boolean {
  return (
    text === LEGACY_PROMPT_TEMPLATE ||
    text === LEGACY_MONTHLY_PROMPT_V1 ||
    text === LEGACY_MONTHLY_PROMPT_V2
  );
}

function normalizeOnePrompt(raw: unknown, dflt: string, legacy: readonly string[]): string {
  if (typeof raw !== "string" || raw.trim().length === 0 || raw.length > 20000) return dflt;
  if (legacy.includes(raw)) return dflt;
  return raw;
}

/** 顶层配置源判定（承担类型收窄：数组与 null 都不是可割接的配置顶层）。 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * 嵌套子源判定（承担类型收窄）：与顶层判定**刻意不同**——历史口径是
 * `typeof x === "object" && x !== null`，数组也算对象源（污染形态的 prompts
 * 数组仍走新形态分支，按缺字段回落新默认）。收窄这一支会改写该边缘形态的行为，
 * 故两条判定分开钉死。
 */
function isObjectSource(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/**
 * 配置文件顶层解析与形状校验（损坏/非对象 → 诊断 + 保持原状，语义与原实现逐字一致：
 * JSON.parse 抛错走「损坏」文案；null/数组/原始值走「顶层非对象」文案）。
 */
function parseConfigDocument(
  deps: UpgradeDeps,
  file: string,
  text: string,
): Record<string, unknown> | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    deps.logger.warn(
      `dsh-provider-usage: 配置文件 ${basename(file)} 损坏，保持原状（下次启动仍按默认归一化读）`,
    );
    return null;
  }
  if (!isPlainObject(parsed)) {
    deps.logger.warn(`dsh-provider-usage: 配置文件 ${basename(file)} 顶层非对象，保持原状`);
    return null;
  }
  return parsed;
}

/**
 * 新形态（prompts 为对象）分支：把「用户从未自定义的旧默认文本」升级为新默认。
 * 返回 null = 三周期均已是目标文本，无改写（幂等）。
 */
function morphExistingPrompts(promptsSrc: Record<string, unknown>): ReportPrompts | null {
  const d = DEFAULT_PROMPTS;
  const morphed: ReportPrompts = {
    daily: normalizeOnePrompt(promptsSrc.daily, d.daily, LEGACY_DAILY),
    weekly: normalizeOnePrompt(promptsSrc.weekly, d.weekly, LEGACY_WEEKLY),
    monthly: normalizeOnePrompt(promptsSrc.monthly, d.monthly, LEGACY_MONTHLY),
  };
  const unchanged =
    promptsSrc.daily === morphed.daily &&
    promptsSrc.weekly === morphed.weekly &&
    promptsSrc.monthly === morphed.monthly;
  return unchanged ? null : morphed;
}

/**
 * 旧单模板分支：旧默认 → 三份新默认；自定义文本 → 三周期同文本（用户文本不丢）。
 * prompts 已是非对象形态（如字符串污染）时同样以展开为准（与归一化同向）。
 * 返回 null = 无可割接的旧单模板（缺键/非字符串/空串/超长），保持原状。
 */
function morphLegacySingleTemplate(src: Record<string, unknown>): ReportPrompts | null {
  const legacy = typeof src.promptTemplate === "string" ? src.promptTemplate : null;
  if (legacy === null || legacy.trim().length === 0 || legacy.length > 20000) return null;
  if (isLegacySingleDefault(legacy)) return { ...DEFAULT_PROMPTS };
  return { daily: legacy, weekly: legacy, monthly: legacy };
}

/**
 * 配置形态割接。幂等：已是新形态即无改写；坏文件保持原状 + 诊断（不抛）。
 * 写失败即抛（调用方中止升级，下次从同一步重跑）。
 */
export async function migrateReportConfig(deps: UpgradeDeps): Promise<void> {
  const file = targetConfigFile(deps.resolveRoot());
  const old = await deps.readOldFile(file);
  if (old.ok === false) return;
  const src = parseConfigDocument(deps, file, old.text);
  if (src === null) return;
  const promptsSrc = isObjectSource(src.prompts) ? src.prompts : null;
  const next =
    promptsSrc !== null ? morphExistingPrompts(promptsSrc) : morphLegacySingleTemplate(src);
  if (next === null) return;
  const out: Record<string, unknown> = { ...src };
  out.prompts = next;
  out.promptTemplate = next.monthly;
  await writeFileAtomic(file, `${JSON.stringify(out, null, 2)}\n`);
  deps.logger.warn(
    `dsh-provider-usage: 配置形态已割接（${basename(file)} 旧默认模板升级为三周期新默认）`,
  );
}

/**
 * dsh-provider-usage — upgrade 域 last-run 迁移（schema 旧 → 全量重算，schema 新 → 温和对齐）。
 *
 * 语义与 server/schedule/store.ts 的 ensureLastRunMigrated 同源（D2 前在 domain2/common/last-run.ts），但文件原语走 S2 注入面
 *（deps.readOldFile 读 + 同域 writeFileAtomic 写），不调业务实例
 *（readLastRun/writeLastRun/updateLastRun/ensureLastRunMigrated 均不导入）。
 * deriveLastRun/alignLastRun/LAST_RUN_SCHEMA 经 server/shared/interface.ts 以纯函数复用
 *（#768 A波4 由 schedule 下沉 shared；零 node 依赖，确定性无副作用；S2 允许的 type+pure 面）。
 *
 * per-root 临界区链留 schedule（METHOD §3 Q1 有主即止）：本步在装配前单线程跑，
 * 无并发写方（preset/执行器尚未装配），直接写安全；装配后的并发写仍走 schedule 的
 * updateLastRun 链，本域不自建临界区、不新建 file-io 叶。
 * 坏文件容错（保持原状 + 诊断，不抛）；写失败即抛。
 */
import { basename, join } from "node:path";
import type { ReportPeriod } from "../config/interface.ts";
import {
  LAST_RUN_SCHEMA,
  alignLastRun,
  deriveLastRun,
  type LastRunRecord,
} from "../shared/interface.ts";
import type { UpgradeDeps } from "./deps.ts";
import { targetLastRunFile, writeFileAtomic } from "./storage-layout.ts";

function indexFile(root: string): string {
  return join(root, "reports", "index.jsonl");
}

function projectLastRun(parsed: Record<string, unknown>): Partial<Record<ReportPeriod, string>> {
  const out: Partial<Record<ReportPeriod, string>> = {};
  for (const period of ["daily", "weekly", "monthly"] as const) {
    const value = parsed[period];
    if (typeof value === "string") out[period] = value;
  }
  return out;
}

/** 普通对象判定（承担类型收窄：数组与 null 都不是可投影的 last-run 顶层）。 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 报告周期白名单（承担类型收窄：非三周期值一律丢弃该行）。 */
function isReportPeriod(value: unknown): value is ReportPeriod {
  return value === "daily" || value === "weekly" || value === "monthly";
}

/**
 * index 记录形状白名单（承担类型收窄）：六个字段逐个按类型校验，任一不符即丢弃该行。
 * 字段集与 common/report-index.ts 同白名单，不导入它以守纯面边界。
 */
function isIndexRecord(value: unknown): value is LastRunRecord {
  if (!isPlainObject(value)) return false;
  return (
    isReportPeriod(value.period) &&
    typeof value.key === "string" &&
    typeof value.endDay === "string" &&
    typeof value.generatedAt === "number" &&
    typeof value.ok === "boolean"
  );
}

/** index.jsonl 单行解析（坏行与形状不符行一律丢弃）。 */
function parseIndexRecord(line: string): LastRunRecord | null {
  let obj: unknown;
  try {
    obj = JSON.parse(line);
  } catch {
    return null;
  }
  return isIndexRecord(obj) ? obj : null;
}

/** index.jsonl 最小解析（坏行跳过）。 */
function parseIndexRecords(raw: string): LastRunRecord[] {
  const out: LastRunRecord[] = [];
  for (const line of raw.split("\n")) {
    const record = parseIndexRecord(line.trim());
    if (record !== null) out.push(record);
  }
  return out;
}

/** last-run 顶层文档解析与形状校验（损坏/非对象 → 诊断 + 保持原状）。 */
function parseLastRunDocument(
  deps: UpgradeDeps,
  file: string,
  text: string,
): { record: Record<string, unknown>; schema: number } | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    deps.logger.warn(`dsh-provider-usage: last-run 文件 ${basename(file)} 损坏，保持原状`);
    return null;
  }
  if (!isPlainObject(parsed)) {
    deps.logger.warn(`dsh-provider-usage: last-run 文件 ${basename(file)} 顶层非对象，保持原状`);
    return null;
  }
  return {
    record: parsed,
    schema: typeof parsed.schema === "number" ? parsed.schema : 1,
  };
}

/** 索引文本读取（读不到 → null = 无事实，不动 last-run）。 */
async function readIndexText(deps: UpgradeDeps, root: string): Promise<string | null> {
  const indexRaw = await deps.readOldFile(indexFile(root));
  return indexRaw.ok === false ? null : indexRaw.text;
}

/**
 * last-run 迁移。幂等：无 index 视作无事实不动；已对齐即无改写；坏文件保持原状 + 诊断。
 */
export async function migrateLastRun(deps: UpgradeDeps): Promise<void> {
  const root = deps.resolveRoot();
  const file = targetLastRunFile(root);
  const raw = await deps.readOldFile(file);
  if (raw.ok === false) return;
  const document = parseLastRunDocument(deps, file, raw.text);
  if (document === null) return;
  const before = projectLastRun(document.record);
  const indexText = await readIndexText(deps, root);
  if (indexText === null) return;
  let indexParsed: LastRunRecord[];
  try {
    indexParsed = parseIndexRecords(indexText);
  } catch {
    deps.logger.warn(`dsh-provider-usage: 报告索引损坏，保持 last-run 原状`);
    return;
  }
  const schema = document.schema;
  const after =
    schema < LAST_RUN_SCHEMA ? deriveLastRun(indexParsed) : alignLastRun(before, indexParsed);
  const changed = schema < LAST_RUN_SCHEMA || JSON.stringify(before) !== JSON.stringify(after);
  if (changed === false) return;
  await writeFileAtomic(
    file,
    `${JSON.stringify({ ...after, schema: LAST_RUN_SCHEMA, updatedAt: Date.now() }, null, 2)}\n`,
  );
  deps.logger.warn(
    `dsh-provider-usage: last-run 已按 index 事实校准（schema ${schema}→${LAST_RUN_SCHEMA}）`,
  );
}

/**
 * dsh-provider-usage — upgrade 域存储归位（historyRoot 内扁平旧形态 → reports/ 子目录）。
 *
 * 两条判据在这里落地：**纯字节搬移**（不 JSON.parse：坏文件的格式知识属各域容错读面，
 * 迁移把它原样搬到新位置）、**归档一律执行**（目标已存在时也不覆盖目标，
 * 旧文件改成固定名留痕 = 幂等标记）。
 *
 * 可再生落点不进迁移：trend/（会话用量趋势明细/聚合分片，缺了由 TrendTracker 按空形态重建，
 * 搬旧值反而可能把过期快照当成新数据）、history/ 下按天分片 JSONL（HistoryStore append
 * 热路径自建，迁移只保证 reports/ 一族；history/ 旧 v3 桶迁移由 HistoryStore.migrateLegacyV3
 * 在装配后处理，不属本链）——缺了由各域按空形态重建。
 *
 * 读经注入（deps.readOldFile 读旧文件字节，不直连 fs 读旧文件）、写经同域原语
 * （writeFileAtomic 0600 原子写）、归档经直接 fs（renameSync 固定名留痕）。
 * 禁新建 file-io 叶（S2 约束）：本文件即存储原语的唯一落点，不另起 shared/file-io。
 */
import { existsSync, renameSync, statSync } from "node:fs";
import { mkdir, rename, rm, writeFile } from "node:fs/promises";
import { randomBytes } from "node:crypto";
import { basename, dirname, join } from "node:path";
import type { UpgradeDeps } from "./deps.ts";
import { LAST_RUN_SCHEMA } from "../shared/interface.ts";

/** 归档后缀：搬完留证据，也是「这一份处理过了」的标记（固定名 → 重跑不累积）。 */
export const MIGRATED_SUFFIX = ".migrated.bak";

/**
 * 空落盘形态。初始形态一律是**版本化空形**而不是全量默认值快照——写全量默认值会把
 * 「用户覆盖过哪些键」这个语义冲掉（文件里每个键都会被读成用户显式提交的）。
 * 读面均容忍 version/schema 附加字段（normalizeReportConfig/readLastRun 白名单投影），
 * 故附加版本字段不改变归一化结果，只起「已落定初始形态」的标记作用。
 */
const EMPTY_CONFIG = `${JSON.stringify({ version: 1 }, null, 2)}\n`;
const EMPTY_LAST_RUN = `${JSON.stringify({ schema: LAST_RUN_SCHEMA }, null, 2)}\n`;

/** 同目标路径的写链：rename 先后在并发下无保证，串行防旧数据盖新数据。 */
const writeChains = new Map<string, Promise<void>>();

function temporaryNameFor(file: string): string {
  return `${file}.${process.pid}.${Date.now().toString(36)}.${randomBytes(6).toString("hex")}.tmp`;
}

async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true, mode: 0o700 });
}

async function writeOnce(file: string, data: string): Promise<void> {
  await ensureDir(dirname(file));
  const temporary = temporaryNameFor(file);
  try {
    await writeFile(temporary, data, { encoding: "utf8", mode: 0o600 });
    await rename(temporary, file);
  } catch (cause) {
    await rm(temporary, { force: true }).catch(() => undefined);
    throw cause;
  }
}

/**
 * 原子写全文（0600，tmp+rename，失败清理临时名后上抛原错误）。
 * version.ts 的刻度回写与三步迁移的落盘统一经此原语（同一目录内相对引用）。
 */
export function writeFileAtomic(file: string, data: string): Promise<void> {
  const previous = writeChains.get(file) ?? Promise.resolve();
  const next = previous.then(
    () => writeOnce(file, data),
    () => writeOnce(file, data),
  );
  writeChains.set(file, next);
  return next.finally(() => {
    if (writeChains.get(file) === next) writeChains.delete(file);
  });
}

/** 旧扁平形态（historyRoot 根下，reports/ 子目录化之前的落点；迁移读面，新代码不得回写）。 */
export function legacyConfigFile(root: string): string {
  return join(root, "config.json");
}

/** 旧扁平形态（同上）。 */
export function legacyLastRunFile(root: string): string {
  return join(root, "last-run.json");
}

/** 新形态：报告配置（运行时读面见 server/config/store.ts 的 reportConfigFile，同字面量）。 */
export function targetConfigFile(root: string): string {
  return join(root, "reports", "config.json");
}

/** 新形态：lastRun 投影（运行时读面见 server/schedule/store.ts，同字面量；D2 前在 domain2/common/last-run.ts）。 */
export function targetLastRunFile(root: string): string {
  return join(root, "reports", "last-run.json");
}

interface LayoutEntry {
  readonly legacy: (root: string) => string;
  readonly target: (root: string) => string;
  readonly initial: string;
}

const LAYOUT: readonly LayoutEntry[] = [
  { legacy: legacyConfigFile, target: targetConfigFile, initial: EMPTY_CONFIG },
  { legacy: legacyLastRunFile, target: targetLastRunFile, initial: EMPTY_LAST_RUN },
];

/**
 * 旧存储 → 新存储布局。逐项独立（一项搬不动不影响其余），但**搬不动都抛出**：
 * 迁移没做完而启动照常，等于让各域按错误的形态去读数据。
 * 幂等：目标已存在即处理过，归档名固定、重跑不累积。
 */
export async function migrateStorageLayout(deps: UpgradeDeps): Promise<void> {
  const root = deps.resolveRoot();
  for (const entry of LAYOUT) {
    await settleOne(entry.legacy(root), entry.target(root), entry.initial, deps);
  }
}

/**
 * 落定一项。目标已存在即视为「这一份处理过了」：不覆盖、只把源文件归档——用户可能已经在新位置改过
 * 东西，用旧文件盖回去等于用历史覆盖现在。initial 为 null 的落点不建文件（本表暂无此形态，保留签名
 * 与 mcp 同构以备 just-in-time 复用）。
 */
export async function settleOne(
  source: string,
  target: string,
  initial: string | null,
  deps: UpgradeDeps,
): Promise<void> {
  if (existsSync(target)) {
    warnIfDowngraded(source, target, deps);
    archive(source);
    return;
  }
  if (existsSync(source)) {
    const old = await deps.readOldFile(source);
    if (old.ok === false) {
      throw new Error(`dsh-provider-usage: 旧存储文件不可读：${basename(source)}`);
    }
    await writeFileAtomic(target, old.text);
    archive(source);
    return;
  }
  const old = await deps.readOldFile(source);
  if (old.ok === true) {
    // 竞态：existsSync 与读之间文件出现（旧文件重现）→ 按有源处理（字节搬移 + 归档）
    await writeFileAtomic(target, old.text);
    archive(source);
    return;
  }
  if (initial !== null) await writeFileAtomic(target, initial);
}

function warnIfDowngraded(source: string, target: string, deps: UpgradeDeps): void {
  if (!existsSync(source)) return;
  let sourceMtime = 0;
  let targetMtime = 0;
  try {
    sourceMtime = statSync(source).mtimeMs;
    targetMtime = statSync(target).mtimeMs;
  } catch {
    return;
  }
  if (sourceMtime <= targetMtime) return;
  deps.logger.warn(
    `dsh-provider-usage: 旧存储文件 ${basename(source)} 比目标更新——检测到更旧的降级写入，将归档旧文件并保留目标`,
  );
}

function isRegularFile(path: string): boolean {
  try {
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

/**
 * 归档源文件；本来就没有就什么都不做。首选固定名（`${source}.migrated.bak` =
 * 「这一份处理过了」的标记，幂等语义不变）；该名已存在（降级写入让旧文件重现）时按
 * `.2`、`.3`……留多代，不覆盖第一代证据。
 */
function archive(source: string): void {
  if (!existsSync(source)) return;
  let target = `${source}${MIGRATED_SUFFIX}`;
  for (let generation = 2; isRegularFile(target); generation += 1) {
    target = `${source}${MIGRATED_SUFFIX}.${generation}`;
  }
  try {
    renameSync(source, target);
  } catch (cause) {
    throw new Error(`dsh-provider-usage: 旧存储文件改名失败：${basename(source)}`, {
      cause,
    });
  }
}

/**
 * dsh-provider-usage — upgrade 域链适配器：把 shared 升级链骨架接到本包的三处落点上
 * （本包步骤表、historyRoot 下的刻度文件、本包 logger 端口）。
 *
 * 链驱动本身（筛选与排序、逐步 await、每步回写、跑完对账、失败文案包装）归
 * shared/upgrade-chain.js；本文件只留接缝，不再是链驱动的一份副本。
 *
 * 落点差异一处：本包刻度随 historyDir 走（刻度读写带 root 参数，见 version.ts），故
 * readScale / writeScale 在这里各包一层闭包；resolveRoot 仍在跑链前调一次，不逐步重解析。
 */
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import {
  pluginVersion,
  runUpgradeChain as runSharedChain,
} from "../../../../../../shared/upgrade-chain.js";
import type { UpgradeDeps } from "../deps.ts";
import { STEPS } from "../steps.ts";
import { readStoredVersion, writeStoredVersion } from "../version.ts";

/** 本模块运行时目录：shared 的 pluginVersion 收起点而不自定位（产物形态与白盒单测深度不同）。 */
const MODULE_DIR = dirname(fileURLToPath(import.meta.url));

/**
 * 装配前跑一遍升级链（组合根在 apply 期 await）。必须在各域装配**之前**：升级会重写存储文件，
 * 先装配就等于让各域读到旧形态，再让它们带着旧形态继续跑。
 */
export function runUpgradeChain(deps: UpgradeDeps): Promise<void> {
  const root = deps.resolveRoot();
  return runSharedChain({
    label: "dsh-provider-usage",
    steps: STEPS,
    deps,
    readScale: () => readStoredVersion(root),
    writeScale: (version) => writeStoredVersion(root, version),
    targetVersion: pluginVersion(MODULE_DIR),
    logger: deps.logger,
  });
}

/**
 * dsh-provider-usage — upgrade 域生命周期：装配期跑完升级链。链动的是磁盘上的文件，
 * 落盘原语是 Promise 面，故装配是异步的。
 *
 * 装配器本体（重复装配即抛、链跑成功后才置标记、release 复位）归 shared 的
 * createUpgradeRunner：同一套语义在三个包里逐字重复过，本域不再留第二份实现。
 */
import { createUpgradeRunner } from "../../../../../shared/upgrade-chain.js";
import type { UpgradeDeps } from "./deps.ts";
import { runUpgradeChain } from "./chain/index.ts";

/** 本域唯一的装配实例：实现由共享层持有，外面 new 不出第二份升级流程。 */
export const upgradeRunner = createUpgradeRunner<UpgradeDeps>(
  "dsh-provider-usage",
  runUpgradeChain,
);

/**
 * dsh-provider-usage — upgrade 域升级步骤表（业务割接 + 空步登记）。
 *
 * 步骤表的唯一职责是登记**本包**的存储形态代际：迁移动作做什么归各 step 文件，链怎么驱动归
 * chain/index.ts 的适配器，步骤的形状（UpgradeStep）归 shared/upgrade-chain.ts。
 */
import type { UpgradeStep } from "../../../../../shared/upgrade-chain.js";
import { migrateLastRun } from "./last-run-morph.ts";
import { migrateReportConfig } from "./config-morph.ts";
import { migrateStorageLayout } from "./storage-layout.ts";
import type { UpgradeDeps } from "./deps.ts";
import { tickUpgradeVersion } from "../../../../../shared/upgrade-tick.js";

/**
 * 步骤表。**新增版本时必须在此追加一项**，哪怕这一步没有数据要改（run 指共享空步）：
 * 链的推进以步骤为刻度，漏掉的版本会让存储刻度永久停在旧值上。
 *
 * fromVersion 取原点而不是某个历史版本：.upgrade-version 是本次才新增的刻度，所有存量安装
 * 的刻度都从 0.0.0 起算，第一步必须对它们全部待办；后两步以前一步目标为起点，失败即停在
 * 上一步刻度，下次从失败步重跑（同刻度多步会让失败步的重试被已推进的刻度跳过）。
 * targetVersion 是**存储形态的代际**（0.2.3 存储归位 / 0.2.4 配置割接 / 0.2.5 last-run），
 * 与 package.json 的 0.2.5 对齐在最后一步（链跑完的对账会把漂移报出来）。
 * 按目标版本升序维护；执行顺序由链驱动排序决定，此处顺序只为便于阅读。
 */
/** 0.2.5 → 0.2.6：用量呈现与模板落盘（#940）+ 节假日判定（#945）+ 存储清理诊断（#934）——新文件缺失即种、余下纯逻辑，无既有形态割接，空步推进刻度。 */
export const STEPS: readonly UpgradeStep<UpgradeDeps>[] = [
  { fromVersion: "0.0.0", targetVersion: "0.2.3", run: migrateStorageLayout },
  { fromVersion: "0.2.3", targetVersion: "0.2.4", run: migrateReportConfig },
  { fromVersion: "0.2.4", targetVersion: "0.2.5", run: migrateLastRun },
  // 0.2.5 → 0.2.6 为空步（用量呈现、节假日判定、存储清理诊断，无既有形态割接）：run 指共享空函数。
  { fromVersion: "0.2.5", targetVersion: "0.2.6", run: tickUpgradeVersion },
  // 0.2.6 → 0.2.7 为空步（本版不含 provider-usage 存储形态变化）：run 指共享空函数。
  { fromVersion: "0.2.6", targetVersion: "0.2.7", run: tickUpgradeVersion },
  // 0.2.7 → 0.2.8 为空步（#1086 校准水位 y 域钳位只动渲染计算，不落盘）：run 指共享空函数。
  { fromVersion: "0.2.7", targetVersion: "0.2.8", run: tickUpgradeVersion },
];

/**
 * dsh-provider-usage — upgrade 域存储刻度落点（historyRoot 下的 .upgrade-version 文件）。
 *
 * 刻度读写原语归本域：落点是**本包的事实**（文件名与所在目录），而读到什么算哪个版本、
 * 版本之间怎么比、怎么从包清单取插件版本，统统归 shared/upgrade-chain.js。
 *
 * 与 mcp-manager 的差异只有一处：刻度随 historyDir 走（root 由调用方给），不散在 DSH_HOME 根。
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { writeFileAtomic } from "./storage-layout.ts";

/** 没有版本文件时的起点：从未升级过。 */
const BASELINE_VERSION = "0.0.0";

/** 存储版本文件（historyRoot 下；刻度随 historyDir 走）。 */
export function upgradeVersionFile(root: string): string {
  return join(root, ".upgrade-version");
}

/**
 * 读存储版本。没有版本文件 = 从未升级过 = 从零跑整条链：每一步都会自己判断
 * 有没有它的活要干，全新安装下只有「落定初始形态」那部分生效。
 */
export async function readStoredVersion(root: string): Promise<string> {
  let text: string;
  try {
    text = await readFile(upgradeVersionFile(root), "utf8");
  } catch {
    return BASELINE_VERSION;
  }
  const trimmed = text.trim();
  return trimmed === "" ? BASELINE_VERSION : trimmed;
}

/**
 * 写存储版本：一步升级完成即推进一档。写不进去即抛，调用方中止这一次升级、
 * 下次从同一步重跑。0600 原子写经存储归位同域原语（同一目录内相对引用）。
 */
export async function writeStoredVersion(root: string, version: string): Promise<void> {
  await writeFileAtomic(upgradeVersionFile(root), version + "\n");
}

